		fails += 1


func _lin(c: float) -> float:
	return c / 12.92 if c <= 0.04045 else pow((c + 0.055) / 1.055, 2.4)


# Linear luma mean and per-channel mean of an RGBA8 layer image (sRGB bytes -> linear).
func _mean(img: Image) -> Array:
	var lut := PackedFloat32Array()
	lut.resize(256)
	for i in 256:
		lut[i] = _lin(i / 255.0)
	var d := img.get_data()
	var s := Vector3.ZERO
	var n := d.size() / 4
	for p in n:
		s += Vector3(lut[d[p * 4]], lut[d[p * 4 + 1]], lut[d[p * 4 + 2]])
	s /= n
	return [s.dot(Vector3(0.2126, 0.7152, 0.0722)), s]


