	_check("arrays_exist", StoneTex.t1_a != null and StoneTex.t1_n != null and StoneTex.t2_a != null and StoneTex.t2_n != null)
	if StoneTex.t1_a == null or StoneTex.t2_a == null:
		_done()
		return
	_check("t1_a_layers", StoneTex.t1_a.get_layers() == 6 and StoneTex.t1_a.get_width() == 512, "%dx%d" % [StoneTex.t1_a.get_layers(), StoneTex.t1_a.get_width()])
	_check("t1_n_layers", StoneTex.t1_n.get_layers() == 6 and StoneTex.t1_n.get_width() == 512)
	_check("t2_a_layers", StoneTex.t2_a.get_layers() == 12 and StoneTex.t2_a.get_width() == 256, "%dx%d" % [StoneTex.t2_a.get_layers(), StoneTex.t2_a.get_width()])
	_check("t2_n_layers", StoneTex.t2_n.get_layers() == 12 and StoneTex.t2_n.get_width() == 256)
	_check("ready", ok)
	_check("src_is_import", StoneTex.src == "import", StoneTex.src)
	_check("format_compressed", StoneTex.format_name() in ["S3TC", "ETC2"], StoneTex.format_name())
	# the layer table: 18 names, each (array, layer) once, tables of the right length
	var seen := {}
