extends Node3D
## Wave 67 P3: the object-space stone texture anchor survives a break.
## A stone's texture coordinate is `local vertex + CpuMesh.anchor`. A piece is re-centred at its centroid (StoneMesh.merged subtracts the
## shift), so without the anchor the grain restarts at every break and jumps at the cut. Every producer of a cell copies the anchor of its
## source; merged() adds the shift; a world boulder's cells carry the node's origin (the world position is what the scenery boulder and the
## RockNode shader sample), so chunks carry origin + off and a chunk of a chunk keeps the chain.
## Run: godot --headless --path . res://world/looks/anchor_test.tscn [-- kinds=granite,flint hits=8]
## Works on a tree WITHOUT the field too (the red log): a missing anchor reads as ZERO.
## Lines: ANCHOR_SEAM (per kind), ANCHOR_CHECK name ok|FAIL note, ANCHOR_DONE fails=N.
var fails := 0
var _id := 971000
const TOL := 1e-5            # m: the seam gate (float32 coordinates up to ~30 m: eps 2e-6)


func _check(name: String, ok: bool, note := "") -> void:
	if not ok:
		fails += 1
	print("ANCHOR_CHECK %s %s %s" % [name, "ok" if ok else "FAIL", note])


static func _anchor(m: CpuMesh) -> Vector3:
	var a: Variant = m.get("anchor")
	return a if a is Vector3 else Vector3.ZERO


func _ready() -> void:
	Engine.set_meta("autotest", true)
	RockNode.cpu_clock = true
	_run.call_deferred()


func _arg(key​: [скрыто], def: String) -> String:
	for a in OS.get_cmdline_user_args():
		if a.begins_with(key​ + "="):
			return a.substr(key.length() + 1)
	return def


# Spatial hash of the parent's vertices: rounded 1 mm cell -> [Vector3 position, Vector3 truth] (truth = what the parent shows there).
func _index(cells: Array, truth_of: Callable) -> Dictionary:
	var h := {}
	for c: CpuMesh in cells:
		for s: Array in c.surfaces:
			for p: Vector3 in s[0]:
				var k := Vector3i((p * 1000.0).round())
				if not h.has(k):
					h[k] = []
				(h[k] as Array).append([p, truth_of.call(p)])
	return h


func _find(h: Dictionary, q: Vector3) -> Variant:
	var k := Vector3i((q * 1000.0).round())
	for dx in range(-1, 2):
		for dy in range(-1, 2):
			for dz in range(-1, 2):
				var l: Variant = h.get(k + Vector3i(dx, dy, dz))
				if l == null:
					continue
				for e: Array in l:
					if (e[0] as Vector3).distance_to(q) < 2e-6:
						return e
	return null


# The seam number of one chunk: over its vertices that coincide with a vertex of the parent (in the parent's space, p = local + off),
# max |(local + anchor) - truth(p)| where truth = the texture coordinate the PARENT has at p (origin + p for a boulder: the world position).
func _seam(chunk: Dictionary, parent: Dictionary, st: Dictionary) -> void:
	var m: CpuMesh = chunk.mesh
	var off: Vector3 = chunk.off
	var a := _anchor(m)
	for s: Array in m.surfaces:
		for v: Vector3 in s[0]:
			var hit: Variant = _find(parent, v + off)
			st.verts = int(st.verts) + 1
			if hit == null:
				continue                          # (a corner the cut made: not on the parent's vertices)
			st.matched = int(st.matched) + 1
			var d: float = ((v + a) - (hit[1] as Vector3)).length()
			st.max = maxf(float(st.max), d)
			if d > TOL:
				st.bad = int(st.bad) + 1


func _blow(r: RockNode, rng: RandomNumberGenerator, tool: Variant, e: float) -> bool:
	var d := Vector3(rng.randfn(), rng.randfn(), rng.randfn()).normalized()
	var hit := RockNode.surface_hit(r.cells(), r.bounds().get_center() + d * (r.size * 3.0), -d, r.size * 4.0)
	if hit.is_empty():
		return false
	var im := Impact.rock(tool, e, r.kind)
	await r.apply_hit(r.to_global(hit.point), r.global_basis * hit.normal, -(r.global_basis * hit.normal),
		clampf(float(im.bite), 0.0, RockSystem.MAX_BITE), clampf(float(im.tip), 0.002, 0.05), float(im.energy),
		RockSystem.blow_force(tool, im), Callable(), e)
	while r.busy():
		await get_tree().process_frame
	return true


# A chunk made a stone, as StoneSystem does: its cells in a proxy at the stone's transform (cells_xf = xf * -off).
func _proxy(kind: String, chunk: Dictionary, xf: Transform3D, fab: Dictionary) -> RockNode:
	_id += 1
	var p := RockNode.new()
	p.setup_proxy(_id, -_id, kind, (chunk.cells as Array).duplicate(), [], 0, fab)
	add_child(p)
	p.global_transform = xf * Transform3D(Basis(), -(chunk.off as Vector3))
	return p


